    unsigned long loopEnd = header->m_loopEnd < 0 ? 0 : header->m_loopEnd + 1;
    format.m_loopStart = format.SamplesToBytes(loopStart);
    format.m_loopEnd = format.SamplesToBytes(loopEnd);
